    }

    @Override
    public void doPost(HttpServletRequest request, HttpServletResponse response)
            throws ServletException, IOException {
        response.setContentType("text/html;charset=UTF-8");

        String param = request.getParameter("BenchmarkTest00378");
        if (param == null) param = "";

        // Encode the parameter to prevent XSS
        String encodedParam = encodeForHTML(param);

        StringBuilder sbxyz85125 = new StringBuilder(encodedParam);
        String bar = sbxyz85125.append("_SafeStuff").toString();

        response.setHeader("X-XSS-Protection", "0");
        Object[] obj = {"a", "b"};
        response.getWriter().format(bar, obj);
    }

    // Method to encode HTML special characters
    private String encodeForHTML(String input) {
        if (input == null) return "";
        return input.replace("&", "&amp;")
                    .replace("<", "&lt;")
                    .replace(">", "&gt;")
                    .replace("\"", "&quot;")
                    .replace("'", "&#x27;");
    }
}

